        .ad-popup-box {
        position: relative;
        max-width: 450px;
        width: 85%;
        background: #fff;
        padding: 8px; 
        border-radius: 15px; 
        transform: scale(0.7); 
        transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .ad-popup-overlay.active {
        display: flex;
        }
        .ad-popup-overlay.active .ad-popup-box {
        transform: scale(1);
